class Employee {
    protected String name;
    public Employee(String name) { this.name = name; }
    public void performWork() {
        System.out.println(name + " performing standard duties");
    }
}

class SoftwareEngineer extends Employee {
    public SoftwareEngineer(String name) { super(name); }

    @Override
    public void performWork() {
        System.out.println(name + " writing production Java code and reviewing PRs");
    }

    public void deployBuild() {
        System.out.println(name + " deploying microservice to Kubernetes cluster");
    }
}

public class UpcastingDemo {
    // Parameter upcasting: accepts any Employee subclass
    public static void assignTask(Employee emp) {
        emp.performWork(); // Dynamic dispatch
    }

    // Return value upcasting: returns SoftwareEngineer as Employee
    public static Employee recruitEngineer() {
        return new SoftwareEngineer("Maya Lin"); // Implicit upcast!
    }

    public static void main(String[] args) {
        SoftwareEngineer se = new SoftwareEngineer("Alex Rivera");

        // 1. Implicit Upcasting via variable assignment
        Employee e1 = se;

        // 2. Explicit Upcasting (redundant but legal)
        Employee e2 = (Employee) se;

        // 3. Upcasting in method parameter
        assignTask(se);

        // 4. Upcasting in method return
        Employee hired = recruitEngineer();
        hired.performWork();
    }
}

