public class UniversalUpcastDemo {
    public static void inspectObject(Object obj) {
        System.out.println("Runtime Class: " + obj.getClass().getSimpleName());
        System.out.println("String representation: " + obj.toString());
    }

    public static void main(String[] args) {
        // Any reference in Java can be implicitly upcast to Object
        inspectObject("LearnBySelf");
        inspectObject(Integer.valueOf(2026));
        inspectObject(new double[]{1.1, 2.2});
    }
}

