class CloudServer {
    public String getSpecs() {
        return "Standard 4GB RAM, 2 vCPU";
    }
}

class HighMemServer extends CloudServer {
    @Override
    public String getSpecs() {
        return "64GB RAM, 16 vCPU";
    }
}

class GpuServer extends CloudServer {
    @Override
    public String getSpecs() {
        return "NVIDIA H100 80GB VRAM";
    }
}

class CloudFactory {
    public static CloudServer createComputeNode(String tier) {
        if (tier.equals("gpu")) return new GpuServer();
        return new HighMemServer();
    }
}

public class Main {
    public static void main(String[] args) {
        CloudServer s1 = CloudFactory.createComputeNode("highmem");
        CloudServer s2 = CloudFactory.createComputeNode("gpu");
        System.out.println("Server 1: " + s1.getSpecs());
        System.out.println("Server 2: " + s2.getSpecs());
    }
}

