class Dog extends Animal {
    public void bark() { System.out.println("Woof!"); }
}

public class BrokenCast {
    public static void main(String[] args) {
        // BUG: In the heap this is a raw Animal, NOT a Dog! Throws ClassCastException!
        // Animal a = new Animal();
        // Dog d = (Dog) a;

        // Fix: Instantiate Dog
        Animal a = new Dog();
        Dog d = (Dog) a;
        d.bark();
    }
}

