class SystemEvent {
    protected String timestamp;
    public SystemEvent(String ts) { this.timestamp = ts; }
    public void logEvent() {
        System.out.println("[" + timestamp + "] Generic system event");
    }
}

class UserLoginEvent extends SystemEvent {
    private String username;
    public UserLoginEvent(String ts, String user) {
        super(ts);
        this.username = user;
    }
    @Override
    public void logEvent() {
        System.out.println("[" + timestamp + "] User " + username + " logged in from IP 10.0.0.1");
    }
}

class PaymentEvent extends SystemEvent {
    private double amount;
    public PaymentEvent(String ts, double amount) {
        super(ts);
        this.amount = amount;
    }
    @Override
    public void logEvent() {
        System.out.println("[" + timestamp + "] Payment $" + amount + " captured via Stripe");
    }
}

class AlertEvent extends SystemEvent {
    private String alertText;
    public AlertEvent(String ts, String text) {
        super(ts);
        this.alertText = text;
    }
    @Override
    public void logEvent() {
        System.out.println("[" + timestamp + "] CRITICAL: " + alertText);
    }
}

public class Main {
    public static void main(String[] args) {
        SystemEvent[] queue = new SystemEvent[] {
            new UserLoginEvent("09:00:01", "admin"),
            new PaymentEvent("09:00:05", 99.0),
            new AlertEvent("09:00:10", "CPU usage exceeded 95%")
        };
        for (SystemEvent e : queue) {
            e.logEvent();
        }
    }
}
